insert into entrevista_partes (slug, numero, titulo, titulo_en, resumo, foto, foto_alt) values ('primeiras-impressoes', 1, 'Primeiras impressões', 'First impressions', 'O entrevistador quebra o gelo: como você está, quem é, o que faz e onde mora. Respostas curtas, sorriso e frases completas.', '/img/banco/comissaria-aviao-miniatura.jpg', 'Comissária sorridente segurando um avião em miniatura') on conflict (slug) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 1, 'How are you?', 'Como você está?', array['How are you doing?']::text[], 'I''m very well, thank you. And how are you?', 'Devolva a pergunta: mostra educação e segurança.', 'primeiras-impressoes:0' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 2, 'Are you nervous?', 'Você está nervoso(a)?', '{}'::text[], 'A little, but in a good way. I''m excited about this opportunity.', 'Admitir um pouco de nervosismo é natural; termine com algo positivo.', 'primeiras-impressoes:1' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 3, 'What''s your name?', 'Qual é o seu nome?', array['What''s your first name?', 'What''s your last name?', 'What''s your full name?']::text[], 'My name is [full name], but you can call me [first name].', null, 'primeiras-impressoes:2' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 4, 'Is this the first time you''re applying for this job?', 'É a primeira vez que você se candidata a esta vaga?', '{}'::text[], 'Yes, it is. I''ve been preparing for this moment for a long time.', 'Se não for a primeira vez, diga o que melhorou desde a última tentativa.', 'primeiras-impressoes:3' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 5, 'What do you do?', 'O que você faz (profissão)?', array['What''s your occupation?', 'What''s your profession?', 'What do you do for a living?', 'How do you make a living?']::text[], 'I work as a [job] at [company]. I deal with customers every day, which I really enjoy.', null, 'primeiras-impressoes:4' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 6, 'How long have you been working as a [job]?', 'Há quanto tempo você trabalha como [profissão]?', '{}'::text[], 'I''ve been working as a [job] for [two] years.', 'Use o present perfect continuous: I''ve been working… for…', 'primeiras-impressoes:5' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 7, 'How old are you?', 'Quantos anos você tem?', '{}'::text[], 'I''m [twenty-six] years old.', null, 'primeiras-impressoes:6' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 8, 'Where do you live?', 'Onde você mora?', '{}'::text[], 'I live in [neighborhood], in [city].', null, 'primeiras-impressoes:7' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 9, 'Do you like living there? Why?', 'Você gosta de morar lá? Por quê?', '{}'::text[], 'Yes, I do. It''s a quiet neighborhood, and it''s close to everything I need.', null, 'primeiras-impressoes:8' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 10, 'How long have you lived there?', 'Há quanto tempo você mora lá?', '{}'::text[], 'I''ve lived there for [five] years.', null, 'primeiras-impressoes:9' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 11, 'How far is it from here?', 'É longe daqui?', '{}'::text[], 'It''s about [forty] minutes from here by subway.', null, 'primeiras-impressoes:10' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 12, 'Who do you live with?', 'Com quem você mora?', '{}'::text[], 'I live with my [parents and my younger sister].', null, 'primeiras-impressoes:11' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 13, 'How many people are there in your house?', 'Quantas pessoas moram na sua casa?', array['How many people are there in your apartment?']::text[], 'There are [four] people: my parents, my sister and me.', null, 'primeiras-impressoes:12' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 14, 'Do you have any brothers or sisters?', 'Você tem irmãos?', '{}'::text[], 'Yes, I have [one older brother]. We get along very well.', null, 'primeiras-impressoes:13' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 15, 'What is he like?', 'Como ele é? (personalidade)', array['What is she like?']::text[], 'He''s very funny and hard-working. He''s also my best friend.', '“What is he like?” pede personalidade, não aparência.', 'primeiras-impressoes:14' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 16, 'Where are you from?', 'De onde você é?', array['Where do you come from?']::text[], 'I''m from [city], in [state], Brazil.', null, 'primeiras-impressoes:15' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 17, 'Where were you born?', 'Onde você nasceu?', '{}'::text[], 'I was born in [city].', null, 'primeiras-impressoes:16' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 18, 'When were you born?', 'Quando você nasceu?', array['When is your birthday?']::text[], 'I was born on [March 3rd, 1999].', null, 'primeiras-impressoes:17' from entrevista_partes where slug = 'primeiras-impressoes' on conflict (origem) do nothing;
insert into entrevista_partes (slug, numero, titulo, titulo_en, resumo, foto, foto_alt) values ('rotina-e-familia', 2, 'Hobbies, família e rotina', 'Hobbies, family and routine', 'Agora o entrevistador quer conhecer seu dia a dia: o que você gosta de fazer, como é sua família e se você é pontual e independente.', '/img/banco/familia-praia.jpg', 'Família sorrindo e brincando na praia') on conflict (slug) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 1, 'What''s your hobby?', 'Qual é o seu hobby?', array['What do you like to do?', 'What do you like doing?']::text[], 'I love traveling and trying new food. I also like going to the gym.', null, 'rotina-e-familia:0' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 2, 'What don''t you like to do? Why?', 'O que você não gosta de fazer? Por quê?', '{}'::text[], 'I don''t like staying at home all weekend. I prefer being active and meeting people.', null, 'rotina-e-familia:1' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 3, 'Do you like to read?', 'Você gosta de ler?', '{}'::text[], 'Yes, I do. I usually read before going to bed.', null, 'rotina-e-familia:2' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 4, 'What kind of books do you like to read?', 'Que tipo de livro você gosta de ler?', array['What sort of books don''t you like to read? Why?']::text[], 'I like biographies and travel books, because I learn from other people''s experiences.', null, 'rotina-e-familia:3' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 5, 'Have you read any good books recently?', 'Você leu algum livro bom recentemente?', array['Have you read any great books lately?', 'Tell me about it.']::text[], 'Yes, I have. I''ve just read [title]. It''s about [short summary], and it taught me [lesson].', 'Prepare um livro de verdade e saiba resumir em duas frases.', 'rotina-e-familia:4' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 6, 'Do you like music?', 'Você gosta de música?', array['What kind of music do you like?', 'What kind of music don''t you like? Why?']::text[], 'Yes, I love music. I listen to pop and Brazilian music, especially when I''m driving.', null, 'rotina-e-familia:5' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 7, 'What do you like to do in your free time?', 'O que você gosta de fazer no tempo livre?', array['What do you like to do in your spare time?']::text[], 'In my free time, I like going to the beach, watching movies and spending time with my friends.', null, 'rotina-e-familia:6' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 8, 'What kind of person are you?', 'Que tipo de pessoa você é?', '{}'::text[], 'I''m a friendly, organized and calm person. I like helping people.', 'Escolha três qualidades ligadas à profissão.', 'rotina-e-familia:7' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 9, 'What are your parents like?', 'Como são seus pais?', array['How do you get along with them?']::text[], 'They''re very kind and supportive. We get along really well.', null, 'rotina-e-familia:8' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 10, 'Do your parents work?', 'Seus pais trabalham?', array['Where do they work?']::text[], 'Yes, they do. My father is a [job] and my mother is a [job].', null, 'rotina-e-familia:9' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 11, 'Do you help them with the expenses?', 'Você ajuda nas despesas de casa?', '{}'::text[], 'Yes, I do. I pay some of the bills, like the internet and groceries.', null, 'rotina-e-familia:10' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 12, 'Are you married or single?', 'Você é casado(a) ou solteiro(a)?', array['Do you have any children?']::text[], 'I''m single.', 'Responda de forma curta e tranquila; não é preciso dar detalhes.', 'rotina-e-familia:11' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 13, 'Are you an independent person?', 'Você é uma pessoa independente?', array['What do you consider an independent person?', 'Is it important to be independent? Why?']::text[], 'Yes, I am. An independent person makes their own decisions and takes care of themselves. It''s very important for a flight attendant, who often lives far from home.', null, 'rotina-e-familia:12' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 14, 'What time do you usually wake up?', 'A que horas você costuma acordar?', array['What time do you usually go to bed?', 'What time do you go to work?']::text[], 'I usually wake up at [six thirty] and go to bed at around [eleven].', null, 'rotina-e-familia:13' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 15, 'What time would you like to start working? Why?', 'A que horas você gostaria de começar a trabalhar? Por quê?', '{}'::text[], 'I don''t mind. I know flight attendants work at any time of the day, and I''m ready for that.', 'Mostre flexibilidade: a escala de voo muda o tempo todo.', 'rotina-e-familia:14' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 16, 'Are you a punctual person?', 'Você é uma pessoa pontual?', array['Are you usually late?', 'Are you always on time?']::text[], 'Yes, I am. I always leave home early to avoid surprises.', null, 'rotina-e-familia:15' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 17, 'Why is it important to be on time?', 'Por que é importante ser pontual?', array['Is it important to be on time?']::text[], 'Because in aviation, a delay affects the whole crew, the passengers and the flight schedule.', null, 'rotina-e-familia:16' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 18, 'How do you feel when you have to wait for someone?', 'Como você se sente quando precisa esperar alguém?', array['Do you like to wait for people?']::text[], 'I don''t mind waiting a little. I usually read something or check my messages.', null, 'rotina-e-familia:17' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 19, 'What do you do when you''re late for an appointment?', 'O que você faz quando está atrasado(a) para um compromisso?', array['Do you usually make excuses?']::text[], 'I call or send a message to let the person know, and I apologize when I arrive.', null, 'rotina-e-familia:18' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 20, 'How often do you go out?', 'Com que frequência você sai?', array['How often do you visit your relatives?']::text[], 'I go out with my friends about once a week, usually on Saturdays.', null, 'rotina-e-familia:19' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 21, 'What do you do when you miss your family?', 'O que você faz quando sente falta da família?', array['What do you do when you miss your friends?', 'Do you miss people easily?']::text[], 'I call them or make a video call. Technology makes it much easier to stay close.', 'A companhia quer saber se você aguenta ficar longe de casa.', 'rotina-e-familia:20' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 22, 'Do you consider yourself a fragile person?', 'Você se considera uma pessoa frágil?', '{}'::text[], 'No, I don''t. I''m sensitive to other people''s feelings, but I''m emotionally strong.', null, 'rotina-e-familia:21' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 23, 'Are you still studying?', 'Você ainda estuda?', array['Why did you stop studying?', 'Don''t you like to study?']::text[], 'Yes, I am. I''m taking an English course and I''ve just finished my flight attendant course.', null, 'rotina-e-familia:22' from entrevista_partes where slug = 'rotina-e-familia' on conflict (origem) do nothing;
insert into entrevista_partes (slug, numero, titulo, titulo_en, resumo, foto, foto_alt) values ('idiomas-e-carreira', 3, 'Idiomas e experiência profissional', 'Languages and work experience', 'Perguntas sobre o seu inglês, outros idiomas, empregos anteriores e por que você quer voar por esta companhia.', '/img/banco/comissaria-painel-voos.jpg', 'Comissária olhando o painel de voos do aeroporto') on conflict (slug) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 1, 'Are you still studying English?', 'Você ainda estuda inglês?', '{}'::text[], 'Yes, I am. I have classes twice a week and I practice every day with podcasts.', null, 'idiomas-e-carreira:0' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 2, 'How long have you been studying English?', 'Há quanto tempo você estuda inglês?', '{}'::text[], 'I''ve been studying English for [four] years.', null, 'idiomas-e-carreira:1' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 3, 'Where did you learn to speak English?', 'Onde você aprendeu a falar inglês?', '{}'::text[], 'I learned it at a language school, and I improved a lot by watching series in English.', null, 'idiomas-e-carreira:2' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 4, 'Do you like speaking English?', 'Você gosta de falar inglês?', '{}'::text[], 'Yes, I love it. It allows me to talk to people from all over the world.', null, 'idiomas-e-carreira:3' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 5, 'How many languages can you speak?', 'Quantos idiomas você fala?', array['How many languages are you able to speak?', 'Do you like any other languages?']::text[], 'I speak Portuguese, English and a little Spanish.', null, 'idiomas-e-carreira:4' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 6, 'What do you like about learning languages?', 'O que você gosta em aprender idiomas?', '{}'::text[], 'I like discovering new cultures through the language.', null, 'idiomas-e-carreira:5' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 7, 'What''s difficult about learning English?', 'O que é difícil em aprender inglês?', array['What''s difficult about learning languages?', 'Do you have any problems when learning languages?']::text[], 'For me, the most difficult part is pronunciation, so I practice it every day.', null, 'idiomas-e-carreira:6' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 8, 'How many jobs have you had so far?', 'Quantos empregos você já teve?', array['How many jobs have you had up to now?']::text[], 'I''ve had [three] jobs so far.', null, 'idiomas-e-carreira:7' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 9, 'Tell me about your experience.', 'Fale sobre sua experiência profissional.', '{}'::text[], 'I worked as a [receptionist] at a hotel for two years. I helped guests from many countries, solved problems and worked in shifts.', 'Ligue sua experiência a atendimento, trabalho em equipe e escala.', 'idiomas-e-carreira:8' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 10, 'Which job did you like best? Why?', 'De qual emprego você gostou mais? Por quê?', array['Which one didn''t you like? Why?']::text[], 'I liked working at the hotel best, because I was in contact with people all the time.', null, 'idiomas-e-carreira:9' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 11, 'Have you ever been fired? Why?', 'Você já foi demitido(a)? Por quê?', array['How many times have you been fired?']::text[], 'No, I haven''t. I left my last job to dedicate myself to the flight attendant course.', 'Se já foi, seja honesto(a) e conte o que aprendeu.', 'idiomas-e-carreira:10' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 12, 'Have you ever caused any problems at work?', 'Você já causou algum problema no trabalho?', '{}'::text[], 'No, I haven''t. I always try to solve conflicts by talking calmly.', null, 'idiomas-e-carreira:11' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 13, 'How do you get along with your superiors?', 'Como é sua relação com seus chefes?', array['How do you usually get along with your co-workers?']::text[], 'I get along very well with them. I respect the hierarchy, and I like working as a team.', null, 'idiomas-e-carreira:12' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 14, 'Why would you like to work at [airline]?', 'Por que você gostaria de trabalhar na [companhia]?', '{}'::text[], 'Because it''s a company that values safety and customer service, and I identify with these values.', 'Pesquise a missão e os valores da companhia antes da entrevista.', 'idiomas-e-carreira:13' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 15, 'Why do you want to work as a flight attendant?', 'Por que você quer ser comissário(a) de voo?', array['Why did you decide to apply for this job?']::text[], 'Because I love taking care of people, I enjoy traveling, and I want a career with responsibility and constant learning.', null, 'idiomas-e-carreira:14' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 16, 'What do you know about [airline]?', 'O que você sabe sobre a [companhia]?', array['What''s your opinion about [airline]?', 'What do you think about [airline]?']::text[], 'I know it''s one of the largest airlines in Brazil, it flies to [destinations] and it''s known for [punctuality / service].', null, 'idiomas-e-carreira:15' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 17, 'Do you know anyone who works at [airline]?', 'Você conhece alguém que trabalha na [companhia]?', array['Who do you know at [airline]?', 'What department does he/she work in?', 'Do you get along with him/her?']::text[], 'Yes, a friend of mine works there as a flight attendant. She told me it''s a great place to work.', null, 'idiomas-e-carreira:16' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 18, 'Has anyone in your family ever worked at [airline]?', 'Alguém da sua família já trabalhou na [companhia]?', array['What did he/she do there?', 'How did he/she like the job?', 'Does he/she speak highly of [airline]?']::text[], 'No, nobody has. I''ll be the first one in my family to work in aviation.', null, 'idiomas-e-carreira:17' from entrevista_partes where slug = 'idiomas-e-carreira' on conflict (origem) do nothing;
insert into entrevista_partes (slug, numero, titulo, titulo_en, resumo, foto, foto_alt) values ('viagens', 4, 'Viagens e o mundo da aviação', 'Travel and aviation', 'O quanto você já vive o estilo de vida de um tripulante: aeroportos, voos, países e companhias aéreas do mundo.', '/img/banco/mapa-mundi-aviao.jpg', 'Avião de brinquedo sobre um mapa-múndi desenhado a giz') on conflict (slug) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 1, 'Do you like planes?', 'Você gosta de aviões?', array['Do you like airports?']::text[], 'Yes, I love them. Airports are full of energy and stories.', null, 'viagens:0' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 2, 'How many airports have you been to?', 'Em quantos aeroportos você já esteve?', array['How many airports do you know?', 'Which one did you like best? Why?', 'Which one didn''t you like? Why?']::text[], 'I''ve been to [six] airports. I liked [Guarulhos] best, because it''s big and very well organized.', null, 'viagens:1' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 3, 'How do you feel when you''re at the airport?', 'Como você se sente quando está no aeroporto?', '{}'::text[], 'I feel excited. It reminds me that I want to work there.', null, 'viagens:2' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 4, 'Have you ever been on a plane?', 'Você já andou de avião?', array['How many times?']::text[], 'Yes, I have. I''ve flown about [ten] times.', null, 'viagens:3' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 5, 'How did you feel when you got on a plane for the first time?', 'Como você se sentiu na primeira vez que entrou num avião?', '{}'::text[], 'I was a little anxious, but the crew was so kind that I felt safe. That''s when I decided to become a flight attendant.', null, 'viagens:4' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 6, 'Have you ever traveled abroad?', 'Você já viajou para o exterior?', array['Where have you been?', 'What countries have you been to?']::text[], 'Yes, I have. I''ve been to [Argentina and Portugal].', null, 'viagens:5' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 7, 'Did you like any particular city? Which one? Why?', 'Gostou de alguma cidade em especial? Qual? Por quê?', array['What cities have you been to?']::text[], 'I really liked [Lisbon] because of its history, the food and the friendly people.', null, 'viagens:6' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 8, 'Which cities would you like to visit? Why?', 'Quais cidades você gostaria de conhecer? Por quê?', '{}'::text[], 'I''d love to visit [Tokyo], because the culture is completely different from ours.', null, 'viagens:7' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 9, 'Would you like to go abroad? Why?', 'Você gostaria de ir para o exterior? Por quê?', array['Do you know anyone there?', 'Do you know anyone who has been there?']::text[], 'Yes, I would. Traveling opens your mind and helps you understand other cultures.', null, 'viagens:8' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 10, 'Would you like to live abroad? Why?', 'Você gostaria de morar no exterior? Por quê?', '{}'::text[], 'Yes, I would, for some time. It would be a great experience to improve my English and become more independent.', null, 'viagens:9' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 11, 'Do you like to travel?', 'Você gosta de viajar?', array['How often do you travel?']::text[], 'Yes, I love it. I try to travel at least twice a year.', null, 'viagens:10' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 12, 'Which cities do you know in Brazil?', 'Quais cidades você conhece no Brasil?', array['Which cities do you know abroad?', 'Which cities do you know overseas?']::text[], 'In Brazil, I know [Rio, Salvador and Florianópolis]. Abroad, I know [Buenos Aires].', null, 'viagens:11' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 13, 'Can you name any famous airlines?', 'Você sabe citar companhias aéreas famosas?', '{}'::text[], 'Sure: Emirates, Lufthansa, British Airways, KLM and Qatar Airways.', null, 'viagens:12' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 14, 'Where is Lufthansa from?', 'De onde é a Lufthansa?', array['Where is British Airways from?', 'Where is JAL from?', 'Where is KLM from?', 'Where is United Airlines from?']::text[], 'Lufthansa is from Germany. British Airways is from the United Kingdom, JAL is from Japan, KLM is from the Netherlands, and United Airlines is from the United States.', null, 'viagens:13' from entrevista_partes where slug = 'viagens' on conflict (origem) do nothing;
insert into entrevista_partes (slug, numero, titulo, titulo_en, resumo, foto, foto_alt) values ('personalidade', 5, 'Personalidade e temperamento', 'Personality and temperament', 'Perguntas para entender como você reage sob pressão, o que te deixa nervoso(a) e como você lida com pessoas. Seja sincero(a) e lembre do perfil da profissão.', '/img/banco/comissaria-cabine-bracos-cruzados.jpg', 'Comissária sorridente de braços cruzados na cabine de passageiros') on conflict (slug) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 1, 'Do you consider yourself a calm person?', 'Você se considera uma pessoa calma?', array['Do you think you are hectic?']::text[], 'Yes, I do. I stay calm even in difficult situations, which is essential on board.', null, 'personalidade:0' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 2, 'What kind of life do you lead?', 'Que tipo de vida você leva?', array['What kind of life would you like to lead?']::text[], 'I lead a busy but balanced life: I work, study and exercise. In the future, I''d like to live a life of travel and new experiences.', null, 'personalidade:1' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 3, 'Do you get tired easily?', 'Você se cansa facilmente?', '{}'::text[], 'No, I don''t. I have a lot of energy, and I take care of my health.', null, 'personalidade:2' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 4, 'Do you exercise?', 'Você pratica exercícios?', array['Do you like to work out?', 'Where do you exercise?']::text[], 'Yes, I do. I go to the gym three times a week, and I go running on weekends.', null, 'personalidade:3' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 5, 'Is it important to exercise? Why?', 'É importante se exercitar? Por quê?', '{}'::text[], 'Yes, it is. It keeps your body and mind healthy, and flight attendants need a lot of physical stamina.', null, 'personalidade:4' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 6, 'Are you a patient person?', 'Você é uma pessoa paciente?', '{}'::text[], 'Yes, I am. I know that each person has their own time.', null, 'personalidade:5' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 7, 'Do you lose your temper easily?', 'Você perde a paciência facilmente?', array['What makes you lose your temper?', 'What makes you angry?']::text[], 'No, I don''t. Injustice bothers me, but I prefer to breathe and talk calmly.', null, 'personalidade:6' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 8, 'What makes you nervous?', 'O que te deixa nervoso(a)?', '{}'::text[], 'Being late makes me nervous, so I always plan ahead.', null, 'personalidade:7' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 9, 'Have you ever lost your temper with your boss?', 'Você já perdeu a paciência com seu chefe?', array['Have you ever lost your temper with your parents?', 'Have you ever lost your temper with your co-workers?']::text[], 'No, I haven''t. When I disagree with someone, I try to talk about it in private and respectfully.', null, 'personalidade:8' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 10, 'Are you afraid of heights?', 'Você tem medo de altura?', array['Are you afraid of flying?']::text[], 'No, I''m not. I actually love flying.', null, 'personalidade:9' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 11, 'What are you afraid of?', 'Do que você tem medo?', array['Do you get scared easily?']::text[], 'I''m afraid of disappointing the people who trust me, so I always do my best.', null, 'personalidade:10' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 12, 'What day is it today?', 'Que dia é hoje?', array['What''s the date today?', 'What time is it now?']::text[], 'Today is [Monday], [November 9th]. It''s [ten thirty].', null, 'personalidade:11' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 13, 'What''s your favorite day of the week? Why?', 'Qual é seu dia da semana favorito? Por quê?', array['What''s your favorite season? Why?']::text[], 'My favorite day is Friday, because I can relax and see my friends. My favorite season is spring.', null, 'personalidade:12' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 14, 'What''s the weather like today?', 'Como está o tempo hoje?', array['What kind of weather do you like?', 'What was the weather like yesterday?']::text[], 'It''s sunny and warm today. Yesterday it was cloudy and rainy.', null, 'personalidade:13' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 15, 'Did you have breakfast this morning?', 'Você tomou café da manhã hoje?', array['What time do you have breakfast?', 'What did you have for breakfast?']::text[], 'Yes, I did. I had coffee, bread and some fruit at seven o''clock.', null, 'personalidade:14' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 16, 'How many meals do you usually have a day?', 'Quantas refeições você costuma fazer por dia?', array['What''s your favorite meal? Why?']::text[], 'I usually have four meals a day. My favorite is lunch, because I can eat with my family.', null, 'personalidade:15' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 17, 'Can you cook?', 'Você sabe cozinhar?', array['Do you know how to cook well?', 'How often do you cook?']::text[], 'Yes, I can. I''m not a chef, but I cook simple and healthy food almost every day.', null, 'personalidade:16' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 18, 'Do you like people?', 'Você gosta de pessoas?', array['Do you like working with the public?']::text[], 'Yes, I do. Working with the public is what motivates me most.', null, 'personalidade:17' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 19, 'Are you shy?', 'Você é tímido(a)?', array['What makes you shy?']::text[], 'Not really. I can be a little quiet at first, but I make friends very easily.', null, 'personalidade:18' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 20, 'If you''re hired, what are your expectations about this job?', 'Se for contratado(a), quais são suas expectativas sobre o trabalho?', '{}'::text[], 'I expect to learn a lot, grow in the company and offer passengers a safe and pleasant flight.', null, 'personalidade:19' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 21, 'What does a flight attendant have to do?', 'O que um comissário de voo faz?', array['What''s a flight attendant''s job?']::text[], 'A flight attendant''s main job is to ensure the safety of passengers. We also provide comfort and good service during the flight.', 'Sempre cite segurança primeiro, depois serviço.', 'personalidade:20' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 22, 'What qualities must a flight attendant have?', 'Que qualidades um comissário deve ter?', array['What''s necessary to become a good flight attendant?']::text[], 'A flight attendant must be calm, polite, responsible and flexible, and must enjoy working as part of a team.', null, 'personalidade:21' from entrevista_partes where slug = 'personalidade' on conflict (origem) do nothing;
insert into entrevista_partes (slug, numero, titulo, titulo_en, resumo, foto, foto_alt) values ('infancia-e-hipoteses', 6, 'Infância, desejos e hipóteses', 'Childhood, wishes and hypotheses', 'Lembranças de infância e perguntas com “I wish” e “If”: o entrevistador testa sua gramática e como você pensa no futuro.', '/img/banco/criancas-brincando.jpg', 'Crianças brincando de patinete e patins numa estrada arborizada') on conflict (slug) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 1, 'What was your childhood like?', 'Como foi sua infância?', array['How was your childhood?', 'Tell me about your childhood.']::text[], 'I had a very happy childhood. I grew up in a big family and spent a lot of time playing outside.', null, 'infancia-e-hipoteses:0' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 2, 'What did you like to do when you were a child?', 'O que você gostava de fazer quando era criança?', array['What did you use to do when you were a kid?']::text[], 'I used to play with my cousins and pretend I was flying a plane.', '“Used to” é ótimo para falar de hábitos do passado.', 'infancia-e-hipoteses:1' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 3, 'Do you like children?', 'Você gosta de crianças?', array['Are you patient with children?']::text[], 'Yes, I do. I''m very patient with them; I have two little nephews.', null, 'infancia-e-hipoteses:2' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 4, 'Have you ever lost your temper with a child?', 'Você já perdeu a paciência com uma criança?', array['What exactly happened?', 'Do you regret it?']::text[], 'No, I haven''t. When a child misbehaves, I try to distract them with something fun.', null, 'infancia-e-hipoteses:3' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 5, 'Can you drive?', 'Você sabe dirigir?', array['How long have you been driving?', 'Do you have a car?', 'What make is your car?']::text[], 'Yes, I can. I''ve been driving for [five] years.', null, 'infancia-e-hipoteses:4' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 6, 'Can you swim?', 'Você sabe nadar?', array['Can you swim well?', 'When did you learn to swim?']::text[], 'Yes, I can. I learned to swim when I was eight.', 'Natação é exigida nas seleções: responda com segurança.', 'infancia-e-hipoteses:5' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 7, 'Have you ever saved anyone from drowning?', 'Você já salvou alguém de se afogar?', '{}'::text[], 'No, I haven''t, but I know the basic procedures from my training.', null, 'infancia-e-hipoteses:6' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 8, 'Where do you wish you were now? Why?', 'Onde você gostaria de estar agora? Por quê?', array['What do you wish you were doing now?']::text[], 'Honestly, I wish I were exactly here, because this interview is very important to me.', 'Com “wish” no presente, use o passado: I wish I were…', 'infancia-e-hipoteses:7' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 9, 'What do you wish you could do tonight?', 'O que você gostaria de poder fazer hoje à noite?', '{}'::text[], 'I wish I could celebrate with my family after this interview.', null, 'infancia-e-hipoteses:8' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 10, 'What do you wish you had done yesterday?', 'O que você gostaria de ter feito ontem?', '{}'::text[], 'I wish I had gone to bed earlier, but I was too excited about today.', null, 'infancia-e-hipoteses:9' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 11, 'Where do you wish you had been born? Why?', 'Onde você gostaria de ter nascido? Por quê?', array['Where do you wish you had worked in the past?']::text[], 'I''m happy I was born in Brazil, but I wish I had lived abroad as a child to learn another language.', null, 'infancia-e-hipoteses:10' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 12, 'Which country do you wish you could have studied in?', 'Em que país você gostaria de ter estudado?', '{}'::text[], 'I wish I could have studied in Canada, because it''s multicultural.', null, 'infancia-e-hipoteses:11' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 13, 'If you had more time, what would you like to do more often?', 'Se tivesse mais tempo, o que gostaria de fazer com mais frequência?', '{}'::text[], 'If I had more time, I would travel and read more.', null, 'infancia-e-hipoteses:12' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 14, 'What would you do if you won a lot of money?', 'O que você faria se ganhasse muito dinheiro?', array['If you had money, what would you like to do?', 'If you were very rich, what would you do?']::text[], 'If I won a lot of money, I would help my family, travel around the world and invest the rest.', null, 'infancia-e-hipoteses:13' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 15, 'Would you quit your job if you won the lottery?', 'Você largaria o emprego se ganhasse na loteria?', '{}'::text[], 'No, I wouldn''t. Flying is my dream, not just a job.', null, 'infancia-e-hipoteses:14' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 16, 'Are you an ambitious person?', 'Você é uma pessoa ambiciosa?', array['What do you think about ambitious people?', 'What do you think about greedy people?']::text[], 'Yes, in a healthy way. I want to grow professionally, but always with ethics. Ambition is good; greed is not.', null, 'infancia-e-hipoteses:15' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 17, 'Who does your laundry?', 'Quem lava sua roupa?', array['Who cooks for you?', 'Who helps you with the housework?']::text[], 'I do it myself. I share the housework with my family.', 'Pergunta indireta sobre independência.', 'infancia-e-hipoteses:16' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 18, 'Can you solve your problems on your own?', 'Você consegue resolver seus problemas sozinho(a)?', array['Do you have many problems?', 'Can you work out your problems by yourself?', 'Who helps you solve your problems?']::text[], 'Yes, I can. But when it''s necessary, I''m not afraid to ask for help.', null, 'infancia-e-hipoteses:17' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 19, 'Do you have to work every day?', 'Você precisa trabalhar todos os dias?', array['What have you had to do recently?']::text[], 'I work from Monday to Friday, and sometimes on Saturdays.', null, 'infancia-e-hipoteses:18' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 20, 'Do you have to get up early? Why?', 'Você precisa acordar cedo? Por quê?', '{}'::text[], 'Yes, I do, because I start work at eight. I''m used to it.', null, 'infancia-e-hipoteses:19' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 21, 'Would you mind working on weekends?', 'Você se importaria de trabalhar nos fins de semana?', array['Do you like working on weekends?', 'Would you object to working on Saturdays and Sundays? Why?', 'Have you ever had to work on weekends?']::text[], 'Not at all. I know that airlines operate every day, including holidays.', 'Nunca diga que se incomoda: a escala inclui fins de semana e feriados.', 'infancia-e-hipoteses:20' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 22, 'Are you a hard-working person?', 'Você é uma pessoa trabalhadora?', array['How many hours do you work a day?', 'How many hours are you used to working a day?']::text[], 'Yes, I am. I usually work eight hours a day, and I''m used to long shifts.', null, 'infancia-e-hipoteses:21' from entrevista_partes where slug = 'infancia-e-hipoteses' on conflict (origem) do nothing;
insert into entrevista_partes (slug, numero, titulo, titulo_en, resumo, foto, foto_alt) values ('decisoes-e-encerramento', 7, 'Decisões, hábitos e encerramento', 'Decisions, habits and wrap-up', 'Perguntas sobre tempo (how long ago, how long does it take), decisões, hábitos e a sua opinião sobre a entrevista.', '/img/banco/comissaria-e-piloto.jpg', 'Comissária e piloto lado a lado na cabine de passageiros') on conflict (slug) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 1, 'What should you do if you want to become a good flight attendant?', 'O que fazer para se tornar um bom comissário?', array['What should you do if you want to work at [airline]?']::text[], 'You should study hard, keep learning languages, take care of your health and always put safety first.', null, 'decisoes-e-encerramento:0' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 2, 'What should you do to get rich?', 'O que fazer para ficar rico(a)?', array['If you wanted to become famous, what would you do?']::text[], 'You should work hard, save money and invest wisely.', null, 'decisoes-e-encerramento:1' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 3, 'When was the last time you ate out?', 'Quando foi a última vez que você comeu fora?', array['Where did you go?']::text[], 'Last weekend. I went to a Japanese restaurant with my friends.', null, 'decisoes-e-encerramento:2' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 4, 'When was the last time you read a book?', 'Quando foi a última vez que você leu um livro?', '{}'::text[], 'I''m reading one right now: [title].', null, 'decisoes-e-encerramento:3' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 5, 'How long ago did you wake up?', 'Há quanto tempo você acordou?', array['How long ago did you have breakfast?', 'How long ago did you get here?']::text[], 'I woke up about four hours ago, and I got here twenty minutes ago.', '“Ago” vem depois do tempo: two hours ago.', 'decisoes-e-encerramento:4' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 6, 'How long does it take you to get to work?', 'Quanto tempo você leva para chegar ao trabalho?', array['How long does it take you to eat your meals?', 'How long does it take you to get dressed?']::text[], 'It takes me about thirty minutes by bus.', null, 'decisoes-e-encerramento:5' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 7, 'Does it take you a long time to make a decision?', 'Você demora para tomar decisões?', array['Does it take you a long time to make up your mind?']::text[], 'No, it doesn''t. I think about the options quickly and make a decision. On board, there''s no time to hesitate.', null, 'decisoes-e-encerramento:6' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 8, 'Do you have presence of mind?', 'Você tem presença de espírito (reage bem sob pressão)?', array['Why is it important to have presence of mind?']::text[], 'Yes, I do. It''s important because in an emergency, a flight attendant must act quickly and correctly.', null, 'decisoes-e-encerramento:7' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 9, 'If you hadn''t come here today, where would you have gone?', 'Se não tivesse vindo aqui hoje, aonde teria ido?', array['If you hadn''t come here today, what would you have done?']::text[], 'If I hadn''t come here today, I would have gone to work.', 'Terceira condicional: If I hadn''t…, I would have…', 'decisoes-e-encerramento:8' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 10, 'If you hadn''t applied for a job here, which airline would you have chosen?', 'Se não tivesse se candidatado aqui, qual companhia teria escolhido?', '{}'::text[], 'Honestly, this was my first choice. I really admire this company.', null, 'decisoes-e-encerramento:9' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 11, 'What''s your opinion about our country?', 'Qual sua opinião sobre o nosso país?', '{}'::text[], 'Brazil is a beautiful and diverse country with very warm people, and that''s something I want to show passengers.', null, 'decisoes-e-encerramento:10' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 12, 'Do you smoke?', 'Você fuma?', '{}'::text[], 'No, I don''t.', null, 'decisoes-e-encerramento:11' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 13, 'Do you drink?', 'Você bebe?', array['What''s your favorite drink?', 'Do you like alcoholic beverages?']::text[], 'Only socially, on special occasions. My favorite drink is orange juice.', null, 'decisoes-e-encerramento:12' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 14, 'What are you good at?', 'No que você é bom/boa?', '{}'::text[], 'I''m good at communicating with people and staying calm under pressure.', null, 'decisoes-e-encerramento:13' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 15, 'What are you not so good at?', 'No que você não é tão bom/boa?', array['What are you terrible at?']::text[], 'I''m not very good at drawing, and I''m not a great singer either!', 'Escolha algo leve, sem relação com a profissão.', 'decisoes-e-encerramento:14' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 16, 'Where do you usually go on weekends?', 'Aonde você costuma ir nos fins de semana?', array['Where do you spend most of your weekends?', 'Where do most of your friends spend their weekends?', 'What do you like to do on weekends?']::text[], 'I usually go to the beach or to a park with my friends.', null, 'decisoes-e-encerramento:15' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 17, 'What did you do yesterday?', 'O que você fez ontem?', array['Where did you spend last weekend?']::text[], 'Yesterday I studied for this interview, went to the gym and had dinner with my family.', null, 'decisoes-e-encerramento:16' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 18, 'What time did you wake up today?', 'A que horas você acordou hoje?', array['How long did it take you to get here today?']::text[], 'I woke up at six, and it took me about an hour to get here.', null, 'decisoes-e-encerramento:17' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 19, 'What did you think about the interview?', 'O que você achou da entrevista?', '{}'::text[], 'I really enjoyed it. Thank you for the opportunity. I hope to be part of your team soon.', 'Agradeça e termine com entusiasmo.', 'decisoes-e-encerramento:18' from entrevista_partes where slug = 'decisoes-e-encerramento' on conflict (origem) do nothing;
insert into entrevista_partes (slug, numero, titulo, titulo_en, resumo, foto, foto_alt) values ('situacoes-a-bordo', 8, 'Situações a bordo', 'On-board situations', 'Casos da rotina do comissário. Mostre que você prioriza a segurança, segue os procedimentos e trata o passageiro com empatia.', '/img/banco/comissaria-demonstracao-seguranca.jpg', 'Comissária fazendo a demonstração de segurança na cabine') on conflict (slug) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 1, 'A drunk passenger is disturbing the others. There are other empty seats. What would you do?', 'Um passageiro embriagado está incomodando os outros. Há assentos vazios. O que você faria?', '{}'::text[], 'I would calmly move the passenger to an empty seat, stop serving alcohol, and offer water or coffee. I would also inform the purser.', null, 'situacoes-a-bordo:0' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 2, 'The same thing happens, but there are no empty seats. What would you do?', 'A mesma situação, mas sem assentos vazios. O que você faria?', '{}'::text[], 'I would talk to the passenger politely but firmly, offer water and something to eat, and keep an eye on him. If the situation got worse, I would inform the purser and the captain.', null, 'situacoes-a-bordo:1' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 3, 'A seat is broken and the passenger can''t move it. There isn''t any other free seat. What would you do?', 'Uma poltrona está quebrada e não há outra livre. O que você faria?', '{}'::text[], 'I would apologize for the inconvenience, try to make the passenger more comfortable with a pillow, and report the problem to maintenance.', null, 'situacoes-a-bordo:2' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 4, 'A passenger boards with his or her pet. What would you do?', 'Um passageiro embarca com o animal de estimação. O que você faria?', '{}'::text[], 'I would check whether the pet is allowed in the cabin according to the airline''s rules. Service dogs are allowed. If it''s not allowed, I would inform the ground staff.', null, 'situacoes-a-bordo:3' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 5, 'A passenger boards with a suitcase that is too big. What would you do?', 'Um passageiro embarca com uma mala grande demais. O que você faria?', '{}'::text[], 'I would politely explain that the bag doesn''t fit in the overhead bin and arrange for it to be checked in the hold.', null, 'situacoes-a-bordo:4' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 6, 'A passenger feels dizzy and asks for help. What would you do?', 'Um passageiro se sente tonto e pede ajuda. O que você faria?', '{}'::text[], 'I would help the passenger sit down, loosen tight clothing, offer water and oxygen if necessary, and stay with him. If he didn''t improve, I would inform the captain and ask if there''s a doctor on board.', null, 'situacoes-a-bordo:5' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 7, 'A passenger is afraid of turbulence. What would you do?', 'Um passageiro tem medo de turbulência. O que você faria?', '{}'::text[], 'I would stay calm, explain that turbulence is normal and that the aircraft is designed for it, and check on the passenger during the flight.', null, 'situacoes-a-bordo:6' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 8, 'A passenger asks for a second helping, but there''s no extra food. What would you do?', 'Um passageiro pede mais comida, mas não há sobra. O que você faria?', array['The same thing happens, but there''s some food left. What would you do?']::text[], 'I would apologize and offer a drink or a snack. If there were food left after the service, I would gladly offer it.', null, 'situacoes-a-bordo:7' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 9, 'You drop a meal tray on a passenger. What would you do?', 'Você derruba a bandeja de refeição em um passageiro. O que você faria?', array['You spill water on a passenger. What would you do?']::text[], 'I would apologize sincerely, help the passenger clean up, offer a towel, and inform the purser so we can offer a cleaning voucher if the airline has one.', null, 'situacoes-a-bordo:8' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 10, 'A passenger can''t eat any of the food on board. What would you do?', 'Um passageiro não pode comer nada do que há a bordo. O que você faria?', '{}'::text[], 'I would check whether a special meal was requested, offer the alternatives we have, such as fruit or snacks, and apologize for the inconvenience.', null, 'situacoes-a-bordo:9' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 11, 'A mother asks for baby food. What would you do?', 'Uma mãe pede comida para o bebê. O que você faria?', array['A mother asks for a baby bottle. What would you do?']::text[], 'I would check what we have on board and offer to warm up her own baby food or bottle.', null, 'situacoes-a-bordo:10' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 12, 'A mother asks for a place to change her baby''s diaper. What would you do?', 'Uma mãe pede um lugar para trocar a fralda do bebê. O que você faria?', '{}'::text[], 'I would show her the lavatory with a baby changing table and offer a bag for the used diaper.', null, 'situacoes-a-bordo:11' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 13, 'A passenger is sitting in the wrong seat. What would you do?', 'Um passageiro está sentado no lugar errado. O que você faria?', array['Two passengers have the same seat number. What would you do?']::text[], 'I would check both boarding passes, politely guide each passenger to the right seat, and contact the ground staff if there was a duplication.', null, 'situacoes-a-bordo:12' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 14, 'A passenger is sitting in first class with an economy ticket. What would you do?', 'Um passageiro está na primeira classe com bilhete econômico. O que você faria?', '{}'::text[], 'I would politely check his boarding pass and kindly ask him to go to his assigned seat.', null, 'situacoes-a-bordo:13' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 15, 'A passenger is smoking on board. What would you do?', 'Um passageiro está fumando a bordo. O que você faria?', '{}'::text[], 'I would ask him to put out the cigarette immediately, explain that smoking is forbidden and dangerous on board, check the area, and inform the captain.', null, 'situacoes-a-bordo:14' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 16, 'You have to return because the destination airport is closed. What would you say?', 'Vocês precisam voltar porque o aeroporto de destino fechou. O que você diria?', '{}'::text[], 'Ladies and gentlemen, due to the closure of the destination airport, we will return to [city]. We apologize for the inconvenience and will give you more information as soon as possible.', null, 'situacoes-a-bordo:15' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 17, 'There''s going to be an emergency landing. What would you say?', 'Haverá um pouso de emergência. O que você diria?', array['You have to give instructions in an emergency. What would you say?']::text[], 'Stay seated! Fasten your seat belts! Heads down, stay down! Follow the crew''s instructions.', 'Comandos de emergência são curtos, firmes e repetidos.', 'situacoes-a-bordo:16' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 18, 'A doctor is needed on board. What would you say?', 'É preciso um médico a bordo. O que você diria?', '{}'::text[], 'Ladies and gentlemen, if there''s a doctor on board, please identify yourself to a crew member. Thank you.', null, 'situacoes-a-bordo:17' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 19, 'A passenger is standing where it''s not allowed. What would you do?', 'Um passageiro está de pé onde não é permitido. O que você faria?', '{}'::text[], 'I would politely ask him to return to his seat and explain that it''s for his own safety.', null, 'situacoes-a-bordo:18' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 20, 'A passenger is arguing with another passenger. What would you do?', 'Um passageiro está discutindo com outro. O que você faria?', array['A passenger is making a lot of noise and disturbing the others. What would you do?']::text[], 'I would calmly approach them, listen to both sides, and try to solve the problem, offering to change seats if possible. If it continued, I would inform the purser.', null, 'situacoes-a-bordo:19' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 21, 'A passenger complains about the food. What would you do?', 'Um passageiro reclama da comida. O que você faria?', '{}'::text[], 'I would listen carefully, apologize, offer another option if available, and register the complaint.', null, 'situacoes-a-bordo:20' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 22, 'A passenger asks to visit the cockpit. What would you do?', 'Um passageiro pede para visitar a cabine de comando. O que você faria?', '{}'::text[], 'I would kindly explain that, for security reasons, visits to the cockpit are not allowed during the flight.', null, 'situacoes-a-bordo:21' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 23, 'A passenger vomits. What would you do?', 'Um passageiro vomita. O que você faria?', '{}'::text[], 'I would help the passenger, offer a sickness bag, water and a towel, clean the area following hygiene procedures, and check whether he needs medical help.', null, 'situacoes-a-bordo:22' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 24, 'A passenger becomes violent and hits the person next to him. What would you do?', 'Um passageiro fica violento e agride quem está ao lado. O que você faria?', '{}'::text[], 'I would separate the passengers, protect the person who was attacked, ask for help from the crew, inform the captain, and follow the airline''s procedures for disruptive passengers.', null, 'situacoes-a-bordo:23' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 25, 'A passenger threatens you with a weapon. What would you do?', 'Um passageiro te ameaça com uma arma. O que você faria?', '{}'::text[], 'I would stay calm, avoid any sudden reactions, and follow the security procedures I learned in training, making sure the captain is informed.', null, 'situacoes-a-bordo:24' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 26, 'A passenger puts the tray under the seat and falls asleep. What would you do?', 'Um passageiro guarda a bandeja embaixo do assento e dorme. O que você faria?', '{}'::text[], 'I would carefully remove the tray without waking the passenger, because items under the seat can block the way in an emergency.', null, 'situacoes-a-bordo:25' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 27, 'A passenger dies during the flight. What would you do?', 'Um passageiro morre durante o voo. O que você faria?', array['A passenger dies before takeoff. What would you do?']::text[], 'I would inform the captain immediately, follow the airline''s procedures, move the passenger to a discreet place if possible, and support any family member traveling with him.', null, 'situacoes-a-bordo:26' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 28, 'A passenger wants something to read. What would you do?', 'Um passageiro quer algo para ler. O que você faria?', '{}'::text[], 'I would offer the in-flight magazine or a newspaper, if available.', null, 'situacoes-a-bordo:27' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 29, 'The plane is about to land and a passenger refuses to fasten his seat belt. What would you do?', 'O avião vai pousar e um passageiro se recusa a apertar o cinto. O que você faria?', '{}'::text[], 'I would explain firmly that it''s mandatory for his safety. If he still refused, I would inform the purser and the captain.', null, 'situacoes-a-bordo:28' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
insert into entrevista_perguntas (parte_id, ordem, en, pt, variantes, modelo, dica, origem) select id, 30, 'The aircraft has a serious technical problem. What would you do?', 'A aeronave tem um problema técnico sério. O que você faria?', '{}'::text[], 'I would stay calm, follow the captain''s instructions and the emergency procedures, and prepare the cabin and the passengers.', null, 'situacoes-a-bordo:29' from entrevista_partes where slug = 'situacoes-a-bordo' on conflict (origem) do nothing;
