-- Cabin Crew · 0020 · Entrevista em inglês editável pelo painel
-- Cria as partes e perguntas no banco e já coloca o conteúdo atual (8 partes, 166 perguntas).
-- Pode rodar mais de uma vez: não duplica nem apaga o que você editou.

create table if not exists entrevista_partes (
  id         serial primary key,
  slug       text not null unique check (slug ~ '^[a-z0-9-]{2,60}$'),
  numero     smallint not null default 1,
  titulo     text not null,
  titulo_en  text,
  resumo     text,
  foto       text,
  foto_alt   text,
  publicado  boolean not null default true,
  created_at timestamptz not null default now()
);

create table if not exists entrevista_perguntas (
  id         uuid primary key default gen_random_uuid(),
  parte_id   int not null references entrevista_partes(id) on delete cascade,
  ordem      int not null default 1,
  en         text not null,
  pt         text,
  variantes  text[] not null default '{}',
  modelo     text,
  dica       text,
  ativo      boolean not null default true,
  origem     text unique,   -- marca o conteúdo que veio da importação inicial
  updated_at timestamptz not null default now()
);
create index if not exists entrevista_perguntas_parte on entrevista_perguntas (parte_id, ordem);

alter table entrevista_partes enable row level security;
alter table entrevista_perguntas enable row level security;

drop policy if exists "alunos leem partes" on entrevista_partes;
create policy "alunos leem partes" on entrevista_partes for select to authenticated using (publicado or is_admin());
drop policy if exists "admin gerencia partes" on entrevista_partes;
create policy "admin gerencia partes" on entrevista_partes for all to authenticated using (is_admin()) with check (is_admin());

drop policy if exists "alunos leem perguntas" on entrevista_perguntas;
create policy "alunos leem perguntas" on entrevista_perguntas for select to authenticated
  using (is_admin() or (ativo and exists (select 1 from entrevista_partes p where p.id = parte_id and p.publicado)));
drop policy if exists "admin gerencia perguntas" on entrevista_perguntas;
create policy "admin gerencia perguntas" on entrevista_perguntas for all to authenticated using (is_admin()) with check (is_admin());

grant select, insert, update, delete on entrevista_partes, entrevista_perguntas to authenticated;
grant usage, select on sequence entrevista_partes_id_seq to authenticated;

